mapper.select:
SELECT T.* FROM (SELECT A.*, F.TESTNAME, B.METHODID, B.ACTIVATEDFLAG AS TESTMETHODFLAG, B.TESTMETHODTYPE, B.TESTCLASS, D.ANALYSISORGID, D.INPUTUSERID, D.INPUTUSERNAME, D.ANALYSISORGNAME, D.METHODSCOPE, D.AUTHENTICATION, D.APPROVAL, C.METHODNAME, C.MAXVERSIONID AS METHODVERSIONID, C.TESTMETHODBASIS, MV.TRIALSCOPE, M.ORGID, M.MONITORTMPLNAME, M.MONITORTMPLGROUPID, G.MONITORTMPLGROUP, E.ACTIVATEDFLAG, E.ITEMGROUPID as TESTITEMGROUPID, H.SORTNUM AS COSTSORTNUM FROM T_EMC_MONITOR_SCHEME A INNER JOIN T_EMC_MONITOR_TMPL M ON A.MONITORTMPLID = M.ID LEFT JOIN T_EMC_TEST_METHOD B ON A.TESTMETHODID = B.ID LEFT JOIN T_EMC_METHOD C ON B.METHODID = C.ID LEFT JOIN T_EMC_METHOD_VERSION MV ON C.MAXVERSIONID = MV.ID LEFT JOIN T_EMC_TEST_CAPACITY D ON B.ID = D.TESTMETHODID AND D.ORGID = M.ORGID LEFT JOIN T_EMC_MONITOR_TMPL_GROUP G ON M.MONITORTMPLGROUPID = G.ID LEFT JOIN T_EMC_TEST F ON A.TESTID = F.ID LEFT JOIN T_EMC_CAPACITY_ITEM_GROUP E ON A.ITEMGROUPID = E.ID LEFT JOIN T_EMC_MONITOR_SCHEME_COST H ON A.SCHEMENAME = H.SCHEMENAME AND H.MONITORTMPLID = A.MONITORTMPLID) T
AND EXISTS (SELECT 1 FROM T_EMC_ORDER_ITEM_GROUP G WHERE G.TESTID = T.TESTID AND G.SCHEMENAME = T.SCHEMENAME AND G.ITEMGROUPID = T.ITEMGROUPID AND G.ORDERID = #{orderId})
AND NOT EXISTS (SELECT 1 FROM T_EMC_ORDER_ITEM_GROUP G WHERE G.TESTID = T.TESTID AND G.SCHEMENAME = T.SCHEMENAME AND G.ITEMGROUP = T.ITEMGROUP AND G.ORDERID = #{orderId})
AND NOT EXISTS (SELECT 1 FROM ${targetTable1} TAR_ WHERE TAR_.${targetSchemeIdColumn} = T.ID
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
)
AND EXISTS (SELECT 1 FROM ${targetTable2} TAR_ WHERE TAR_.${targetMatchColumn} = T.${thisMatchColumn}
AND TAR_.${targetFilterColumn2} = #{targetFilterValue2}
AND TAR_.${targetFilterColumn3} = #{targetFilterValue3}
)
AND NOT EXISTS (SELECT 1 FROM T_EMC_PROJ_ORDER G WHERE G.TESTID = T.TESTID AND G.SCHEMENAME = T.SCHEMENAME AND G.ITEMGROUP = T.ITEMGROUP AND G.PROJSCHEMEID = #{projSchemeId})
AND EXISTS (SELECT 1 FROM T_EMC_ORDER_TASK O WHERE O.TESTID = T.TESTID AND O.SCHEMENAME = T.SCHEMENAME AND O.METHODID = T.METHODID AND O.ORDERID = #{orderId}) AND EXISTS (SELECT 1 FROM T_EMC_ORDER_ITEM_GROUP P WHERE P.ITEMGROUPID = T.ITEMGROUPID AND P.ORDERID = #{orderId})
AND NOT EXISTS (SELECT 1 FROM T_EMC_ORDER_TASK O WHERE O.TESTID = T.TESTID AND O.METHODID = T.METHODID AND O.ORDERID = #{orderId})
AND EXISTS (SELECT 1 FROM T_CORE_USER_PERMISSION UP WHERE UP.PERMISSIONTYPEID = 'T_CORE_ORG' AND UP.TARGETID = T.ORGID AND UP.USERID = #{loginUser.id})
GROUP BY T.ID, T.SCHEMENAME, T.MONITORTMPLID, T.TESTMETHODID, T.TESTID, T.REPORTNAME, T.CREATEDBYID, T.CREATEDBYNAME, T.CREATEDTIME, T.CREATEDBYORGID, T.ITEMGROUPID, T.ITEMGROUP, T.SORTNUM, T.DEFAULTFLAG, T.ENABLEFLAG, T.MONITORSCHEMECOSTID, T.PERIOD, T.TECHPRICE, T.SALEPRICE, T.SKUGBID, T.SKUQUOTEGBID, T.CREATEDBYORGNAME, T.TESTNAME, T.METHODID, T.TESTMETHODFLAG, T.TESTMETHODTYPE, T.TESTCLASS, T.ANALYSISORGID, T.INPUTUSERID, T.INPUTUSERNAME, T.ANALYSISORGNAME, T.METHODNAME, T.METHODVERSIONID, T.TESTMETHODBASIS, T.ORGID, T.MONITORTMPLNAME, T.MONITORTMPLGROUPID, T.MONITORTMPLGROUP, T.ACTIVATEDFLAG, T.COSTSORTNUM
ORDER BY
T.COSTSORTNUM ASC, T.SCHEMENAME DESC, T.SORTNUM ASC, T.ID DESC

SELECT T.*
  FROM T_EMC_MONITOR_SCHEME T
 WHERE T.ID = #{id}
